// Local mapping aid: no auto-click, no POST generated by this script.
import 'dotenv/config';
import fs from 'node:fs';
import { createInterface } from 'node:readline/promises';
import { chromium } from '@playwright/test';
import { config, qaUrl, storageState } from '../src/config.js';

function shape(v, depth=0) {
  if(depth>5) return '[depth limit]';
  if(v===null) return 'null';
  if(Array.isArray(v)) return {type:'array',sample:v.length?shape(v[0],depth+1):'empty'};
  if(typeof v==='object') return Object.fromEntries(Object.keys(v).slice(0,60).filter(k=>!/(token|secret|password|cookie|authorization|api.?key)/i.test(k)).map(k=>[k,shape(v[k],depth+1)]));
  return typeof v;
}
const browser=await chromium.launch({headless:false});
const entries=new Map(); const pending=new Set();
try {
  const origin=qaUrl('/').origin;
  const context=await browser.newContext({storageState:storageState('ceo')});
  context.on('response',response=>{
    const request=response.request(); const u=new URL(response.url());
    if(u.origin!==origin || !['fetch','xhr'].includes(request.resourceType())) return;
    const key=`${request.method()} ${u.pathname}`;
    const p=(async()=>{
      const entry={method:request.method(),path:u.pathname,status:response.status(),queryKeys:[...new Set(u.searchParams.keys())].filter(k=>!/token|secret|password|cookie|key/i.test(k))};
      try {const data=request.postDataJSON(); if(data) entry.requestShape=shape(data);}catch{}
      if((response.headers()['content-type']||'').includes('json')) {
        try {entry.responseShape=shape(await response.json());}catch{}
      } else entry.responseType='non-JSON (possibly streaming)';
      if(entries.size<500||entries.has(key)) entries.set(key,entry);
    })();
    pending.add(p); p.finally(()=>pending.delete(p));
  });
  for(const k of ['UI_CEO_CHAT_PATH','UI_GOAL_PATH','UI_WORKFORCE_PATH']) {
    const page=await context.newPage();
    await page.goto(qaUrl(config(k,{required:true})).toString(),{waitUntil:'domcontentloaded'});
  }
  const rl=createInterface({input:process.stdin,output:process.stdout});
  console.log('Đã mở 3 trang. Chỉ quan sát request; script không tự gửi chat hoặc tạo dữ liệu.');
  console.log('Nếu tenant QA cô lập được phép, bạn có thể thao tác gửi một Goal mẫu và mở kết quả. Nếu không, chỉ xem dữ liệu sẵn có.');
  await rl.question('Quay lại terminal, nhấn Enter để xuất cấu trúc API (không xuất giá trị request/response). '); rl.close();
  let timer; await Promise.race([Promise.allSettled([...pending]),new Promise(r=>{timer=setTimeout(r,5000)})]); clearTimeout(timer);
  fs.mkdirSync('results/groups/GO',{recursive:true});
  fs.writeFileSync('results/groups/GO/discovery.json',JSON.stringify([...entries.values()],null,2));
  console.log('Đã lưu results/groups/GO/discovery.json. Kiểm tra và che thông tin riêng nếu gửi cho người khác.');
} finally {await browser.close();}
